import { defineConfig, devices } from '@playwright/test';

export default defineConfig({
	webServer: {
		command: 'npm run build && npm run preview',
		port: 4173,
		reuseExistingServer: !process.env.CI,
		timeout: 120000, // 2 minutes
		// e2e is seam-only: it never authenticates or hits real Supabase, so the
		// build runs on FAKE public config instead of the real 1Password-injected
		// values (`.env` is a 1Password FIFO, unavailable to a bare `vite build`).
		// This keeps `npm run test:e2e` reproducible with no secrets. Real deploys
		// (Vercel) still inject the real values. `$env/static/public` reads these
		// from process.env at build time; MISTRAL_API_KEY is a dynamic import so it
		// doesn't need faking here.
		env: {
			PUBLIC_SUPABASE_URL: 'http://localhost:54321',
			PUBLIC_SUPABASE_ANON_KEY: 'test-anon-key'
		}
	},
	testDir: 'e2e',
	use: {
		baseURL: 'http://localhost:4173',
		trace: 'on-first-retry'
	},
	// Run tests in headless mode by default
	projects: [
		{
			name: 'chromium',
			use: { ...devices['Desktop Chrome'] }
		}
	],
	// Limit workers to prevent resource issues
	workers: process.env.CI ? 1 : undefined,
	// Ensure tests fail fast
	fullyParallel: false,
	// Retry on CI only
	retries: process.env.CI ? 2 : 0
});
---VITE---
import devtoolsJson from 'vite-plugin-devtools-json';
import tailwindcss from '@tailwindcss/vite';
import { sveltekit } from '@sveltejs/kit/vite';
import { defineConfig } from 'vite';

export default defineConfig({
	plugins: [tailwindcss(), sveltekit(), devtoolsJson()],
	test: {
		expect: { requireAssertions: true },
		testTimeout: 10000, // 10 second timeout for all tests
		hookTimeout: 10000, // 10 second timeout for hooks
		projects: [
			{
				extends: './vite.config.ts',
				test: {
					name: 'client',
					environment: 'browser',
					browser: {
						enabled: true,
						provider: 'playwright',
						instances: [{ browser: 'chromium' }],
						headless: true // Run in headless mode
					},
					include: ['src/**/*.svelte.{test,spec}.{js,ts}'],
					exclude: ['src/lib/server/**'],
					setupFiles: ['./vitest-setup-client.ts']
				}
			},
			{
				extends: './vite.config.ts',
				test: {
					name: 'server',
					environment: 'node',
					include: ['src/**/*.{test,spec}.{js,ts}', 'supabase/functions/**/*.{test,spec}.{js,ts}'],
					exclude: ['src/**/*.svelte.{test,spec}.{js,ts}']
				}
			}
		]
	}
});
---E2E---
e2e:
date-filter-url-preservation.spec.ts
demo.test.ts

tests:
receipt-edit-modal.spec.ts

