/**
 * Family Utility Functions
 *
 * Helper functions for working with family memberships and default families.
 */

import { supabase } from '$lib/supabaseClient';
import type { FamilyMember } from '$lib/utils/familyMembers';

/**
 * Get the default family ID for the current authenticated user
 *
 * @returns The user's default family ID, or null if not found
 */
export async function getDefaultFamilyId(): Promise<string | null> {
	const {
		data: { user }
	} = await supabase.auth.getUser();

	if (!user) {
		return null;
	}

	const { data: familyMembers } = await supabase
		.from('family_members')
		.select('family_id, is_default, status')
		.eq('user_id', user.id)
		.eq('status', 'active')
		.order('is_default', { ascending: false })
		.limit(1);

	return familyMembers?.[0]?.family_id || null;
}

/**
 * Get all active families for the current authenticated user
 *
 * @returns Array of family IDs the user is an active member of
 */
export async function getActiveFamilyIds(): Promise<string[]> {
	const {
		data: { user }
	} = await supabase.auth.getUser();

	if (!user) {
		return [];
	}

	const { data: familyMembers } = await supabase
		.from('family_members')
		.select('family_id')
		.eq('user_id', user.id)
		.eq('status', 'active');

	return familyMembers?.map((fm) => fm.family_id) || [];
}

/**
 * Get the members of the current authenticated user's default family.
 *
 * Reads through the `get_family_members()` SECURITY DEFINER RPC, which resolves
 * each member's primary email (from `auth.users`, unreachable by a direct client
 * query). Returns active members only, ordered by email.
 *
 * @returns The roster of the caller's default family; empty if they have none.
 * @throws  Propagates the Supabase error so the caller can surface it in the UI.
 */
export async function getFamilyMembers(): Promise<FamilyMember[]> {
	const { data, error } = await supabase.rpc('get_family_members');

	if (error) {
		throw error;
	}

	return (data as FamilyMember[] | null) ?? [];
}
