import { describe, it, expect, vi, beforeEach } from 'vitest';
import { render } from 'vitest-browser-svelte';
import {
	pageStore,
	supabaseMock,
	setSession,
	setProfile,
	makeProfile,
	fakeSession,
	resetHarness
} from './harness/appMocks';

// The profile page reads $lib/supabaseClient directly (auth + profiles table).
vi.mock('$app/stores', () => ({ page: pageStore }));
vi.mock('$lib/supabaseClient', () => ({ supabase: supabaseMock }));

import ProfilePage from '../../routes/profile/+page.svelte';

/**
 * Behavior tests for the profile page.
 *
 * Replaces the source-introspection profile-page.spec.ts, which regex'd the page
 * for headers, state vars, and query strings. The email add/edit/delete LOGIC
 * (validation, dedup, slot finding) is covered by profileEmails.spec.ts (32 tests);
 * these render the real page and assert what the user sees and the flows the page
 * wires: the login gate, account info, the additional-emails list, and the add/
 * delete affordances. Built on the route-render harness (harness/appMocks.ts).
 */
describe('profile page', () => {
	beforeEach(resetHarness);

	it('prompts to log in when there is no session', async () => {
		setSession(null);

		const screen = render(ProfilePage);

		await expect
			.element(screen.getByText('Please log in to view and manage your profile.'))
			.toBeVisible();
		await expect.element(screen.getByRole('link', { name: 'Go to Login' })).toBeVisible();
	});

	it('shows account information from the session when signed in', async () => {
		setSession(fakeSession('user-42'));
		setProfile(makeProfile({ user_id: 'user-42' }));

		const screen = render(ProfilePage);

		await expect
			.element(screen.getByRole('heading', { name: 'Account Information' }))
			.toBeVisible();
		// Primary Email is the only field left in this section — the User ID row was
		// deliberately dropped by "Simplify profile page" (aa2938d).
		await expect.element(screen.getByText('Primary Email')).toBeVisible();
		await expect.element(screen.getByText('primary@example.com')).toBeVisible();
	});

	it('lists the additional emails from the profile with the used-slot count', async () => {
		setSession(fakeSession());
		setProfile(makeProfile({ email_1: 'alt1@example.com', email_2: 'alt2@example.com' }));

		const screen = render(ProfilePage);

		await expect.element(screen.getByText('alt1@example.com')).toBeVisible();
		await expect.element(screen.getByText('alt2@example.com')).toBeVisible();
		await expect.element(screen.getByText('2 of 5 email addresses added')).toBeVisible();
	});

	it('shows the empty state when the profile has no additional emails', async () => {
		setSession(fakeSession());
		setProfile(makeProfile());

		const screen = render(ProfilePage);

		await expect
			.element(screen.getByText('No additional email addresses added yet.'))
			.toBeVisible();
	});

	it('opens the add-email form when Add Email is clicked', async () => {
		setSession(fakeSession());
		setProfile(makeProfile());

		const screen = render(ProfilePage);

		await screen.getByRole('button', { name: 'Add Email' }).click();

		await expect.element(screen.getByRole('textbox', { name: 'New email address' })).toBeVisible();
	});

	it('asks for confirmation naming the email when Delete is clicked', async () => {
		setSession(fakeSession());
		setProfile(makeProfile({ email_1: 'doomed@example.com' }));

		const screen = render(ProfilePage);

		await screen.getByRole('button', { name: 'Delete email doomed@example.com' }).click();

		await expect
			.element(screen.getByRole('heading', { name: 'Delete Email Address' }))
			.toBeVisible();
		await expect.element(screen.getByText(/Are you sure you want to delete/)).toBeVisible();
	});
});

