	/**
	 * The read-only family roster, loaded via the `get_family_members` RPC.
	 *
	 * The decoration logic (isCurrentUser / isOwner) is unit-tested in
	 * familyMembers.spec.ts; these cover the part only a render can: that the page
	 * calls the RPC, decorates the result with the session's user id, and renders
	 * each of the four branches (loading / error / empty / populated).
	 *
	 * Every test here uses a profile with no additional emails, so the only <li>
	 * elements on the page are roster rows and `getByRole('listitem')` is
	 * unambiguous.
	 */
	describe('family members roster', () => {
		const roster = [
			// Signed-in user, a plain member — expects "You" and NOT "Owner".
			makeFamilyMember({ user_id: 'user-42', email: 'me@example.com', role: 'member' }),
			// Someone else, who created the family — expects "Owner" and NOT "You".
			makeFamilyMember({ user_id: 'user-99', email: 'partner@example.com', role: 'owner' })
		];

		function signedInWithRoster(): void {
			setSession(fakeSession('user-42'));
			setProfile(makeProfile({ user_id: 'user-42' }));
			setFamilyMembers(roster);
		}

		it('lists every member of the family by email', async () => {
			signedInWithRoster();

			const screen = render(ProfilePage);

			await expect.element(screen.getByRole('heading', { name: 'Family Members' })).toBeVisible();
			await expect.element(screen.getByText('me@example.com')).toBeVisible();
			await expect.element(screen.getByText('partner@example.com')).toBeVisible();
		});

		it('badges the signed-in user as "You" and the family creator as "Owner"', async () => {
			signedInWithRoster();

			const screen = render(ProfilePage);

			// Row order follows the roster, so the badges must land on opposite rows:
			// a mix-up that swapped the flags would still show both badges somewhere.
			const rows = screen.getByRole('listitem');
			await expect.element(rows.nth(0).getByText('You')).toBeVisible();
			await expect.element(rows.nth(1).getByText('Owner')).toBeVisible();
		});

		it('does not badge the signed-in user as Owner when someone else owns the family', async () => {
			signedInWithRoster();

			const screen = render(ProfilePage);

			const rows = screen.getByRole('listitem');
			await expect.element(rows.nth(0).getByText('You')).toBeVisible();
			await expect.element(rows.nth(0).getByText('Owner')).not.toBeInTheDocument();
			await expect.element(rows.nth(1).getByText('You')).not.toBeInTheDocument();
		});

		it('shows the empty state when the roster comes back empty', async () => {
			setSession(fakeSession('user-42'));
			setProfile(makeProfile({ user_id: 'user-42' }));
			setFamilyMembers([]);

			const screen = render(ProfilePage);

			await expect.element(screen.getByText('No family members found.')).toBeVisible();
		});

		it('surfaces an error when the roster RPC fails', async () => {
			setSession(fakeSession('user-42'));
			setProfile(makeProfile({ user_id: 'user-42' }));
			setFamilyMembersError('permission denied for function get_family_members');

			const screen = render(ProfilePage);

			await expect.element(screen.getByText('Failed to load family members')).toBeVisible();
