	// Subscribe to auth state changes synchronously so onMount can return a
	// synchronous cleanup (an async onMount callback can't return a teardown).
	const { data: subscription } = supabase.auth.onAuthStateChange(async (_event, newSession) => {
		session = newSession;
		if (newSession) {
			await loadProfile();
			await loadFamilyMembers();
		} else {
			profile = null;
			familyMembers = [];
		}
	});

	// Initial session load (#{#upp1a})
	void (async () => {
		const { data } = await supabase.auth.getSession();
		session = data.session;
		if (session) {
			await loadProfile();
			await loadFamilyMembers();
		}
		loading = false;
	})();

	return () => {
		subscription.subscription.unsubscribe();
	};
});

